import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import shlex

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
os.makedirs(UPLOAD_DIR, exist_ok=True)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'bmp', 'tiff', 'webp', 'pdf']

def validate_format(fmt):
    """Check if the requested output format is allowed."""
    return fmt.lower().strip() in ALLOWED_FORMATS

def get_density(req):
    """Extract DPI density parameter, default 150."""
    try:
        d = int(req.args.get('density', '150'))
        return min(max(d, 72), 600)
    except (ValueError, TypeError):
        return 150

def build_convert_command(input_path, output_path, output_format, density, extra_opts):
    """Build ImageMagick convert command."""
    cmd = f'convert -density {density}'

    # Apply user-specified resize if provided
    if extra_opts.get('resize'):
        resize_val = extra_opts['resize']
        # Basic validation: should match NxN pattern
        if 'x' in resize_val and len(resize_val) < 20:
            cmd += f' -resize {resize_val}'

    # Apply quality setting
    if extra_opts.get('quality'):
        try:
            q = int(extra_opts['quality'])
            q = min(max(q, 1), 100)
            cmd += f' -quality {q}'
        except (ValueError, TypeError):
            pass

    # Apply colorspace
    colorspace = extra_opts.get('colorspace', '')
    if colorspace in ('RGB', 'CMYK', 'Gray', 'sRGB'):
        cmd += f' -colorspace {colorspace}'

    # Apply custom label/annotation if provided
    label = extra_opts.get('label', '')
    if label:
        cmd += f' -label {label}'

    cmd += f' {shlex.quote(input_path)} {shlex.quote(output_path)}'
    return cmd

@app.route('/convert', methods=['POST'])
def convert_image():
    """Convert uploaded image to specified format."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    output_format = request.form.get('format', 'png').lower().strip()

    if not validate_format(output_format):
        return jsonify({'error': f'Unsupported format: {output_format}'}), 400

    filename = secure_filename(file.filename)
    if not filename:
        return jsonify({'error': 'Invalid filename'}), 400

    # Save uploaded file
    input_path = os.path.join(UPLOAD_DIR, f'input_{os.getpid()}_{filename}')
    file.save(input_path)

    output_filename = os.path.splitext(filename)[0] + '.' + output_format
    output_path = os.path.join(UPLOAD_DIR, f'output_{os.getpid()}_{output_filename}')

    density = get_density(request)

    extra_opts = {
        'resize': request.form.get('resize', ''),
        'quality': request.form.get('quality', ''),
        'colorspace': request.form.get('colorspace', ''),
        'label': request.form.get('label', '')
    }

    cmd = build_convert_command(input_path, output_path, output_format, density, extra_opts)

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        return send_file(output_path, as_attachment=True, download_name=output_filename)

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup
        for p in [input_path, output_path]:
            try:
                os.unlink(p)
            except OSError:
                pass

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
